const novelMissingLocalDataNote = "No local data yet — run 'readwise-pp-cli sync' first."

func novelDBPath(cmd *cobra.Command) string {
	dbPath := defaultDBPath("readwise-pp-cli")
	if flag := cmd.Flags().Lookup("db-path"); flag != nil && strings.TrimSpace(flag.Value.String()) != "" {
		dbPath = flag.Value.String()
	}
	return dbPath
}

func novelLocalStoreExists(cmd *cobra.Command) (bool, error) {
	dbPath := novelDBPath(cmd)
	info, err := os.Stat(dbPath)
	if err == nil {
		if info.IsDir() {
			return false, fmt.Errorf("local database path is a directory: %s", dbPath)
		}
		return true, nil
	}
	if os.IsNotExist(err) {
		return false, nil
	}
	return false, fmt.Errorf("checking local database: %w", err)
}

func novelOpenStore(cmd *cobra.Command) (*store.Store, error) {
	dbPath := novelDBPath(cmd)
	db, err := store.OpenReadOnly(dbPath)
	if err != nil {
		return nil, fmt.Errorf("opening local database: %w\nRun 'readwise-pp-cli sync' first to populate the local database.", err)
	}
	return db, nil
}

