func novelReadableSource(title, author, site string) string {
	title = cliutil.CleanText(title)
	author = cliutil.CleanText(author)
	site = cliutil.CleanText(site)
	if title == "" {
		title = "Untitled"
	}
	if author != "" {
		return title + " — " + author
	}
	if site != "" {
		return title + " — " + site
	}
	return title
}

func novelRenderAskMarkdown(w io.Writer, view novelAskView) error {
	if view.Truncated {
		if _, err := fmt.Fprintf(w, "Results truncated: showing up to %d matches per source.\n\n", novelAskSourceLimit); err != nil {
			return err
		}
	}
	for _, block := range view.Blocks {
		if _, err := fmt.Fprintf(w, "## %s\n\n", block.Source); err != nil {
			return err
		}
		for _, item := range block.Items {
			text := strings.TrimSpace(item.Text)
			if text == "" {
				continue
			}
			if _, err := fmt.Fprintf(w, "- %s", text); err != nil {
				return err
			}
			if item.Note != "" {
				if _, err := fmt.Fprintf(w, "\n  - Note: %s", item.Note); err != nil {
					return err
				}
			}
			if item.URL != "" {
				if _, err := fmt.Fprintf(w, "\n  - Link: %s", item.URL); err != nil {
					return err
				}
			}
			if _, err := fmt.Fprint(w, "\n"); err != nil {
				return err
			}
		}
		if _, err := fmt.Fprint(w, "\n"); err != nil {
			return err
		}
	}
	if view.Note != "" && len(view.Blocks) == 0 {
		_, err := fmt.Fprintln(w, view.Note)
		return err
	}
	return nil
}

