func novelValidDedupeTitleKey(key string) bool {
	if key == "" || novelJunkTitleKeys[key] {
		return false
	}
	seen := map[string]bool{}
	for _, tok := range novelDedupeTitleTokenRe.FindAllString(key, -1) {
		if len(tok) >= 3 {
			seen[tok] = true
		}
	}
	return len(seen) >= 2
}

func novelNormalizeURL(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" {
		if parsed, parseErr := url.Parse("https://" + raw); parseErr == nil && parsed.Host != "" {
			u = parsed
		} else {
			raw = strings.Split(raw, "#")[0]
			raw = strings.TrimPrefix(strings.TrimPrefix(raw, "https://"), "http://")
			raw = strings.TrimPrefix(raw, "www.")
			base, query, _ := strings.Cut(raw, "?")
			base = strings.TrimRight(strings.ToLower(base), "/")
			query = novelFilterTrackingQuery(query)
			if query != "" {
				return base + "?" + query
			}
			return base
		}
	}
	host := strings.TrimPrefix(strings.ToLower(u.Host), "www.")
	path := strings.TrimRight(u.EscapedPath(), "/")
	query := novelFilterTrackingQuery(u.RawQuery)
	if query != "" {
		return host + path + "?" + query
	}
	return host + path
}

func novelFilterTrackingQuery(rawQuery string) string {
	if rawQuery == "" {
		return ""
	}
	values, err := url.ParseQuery(rawQuery)
	if err != nil {
		return rawQuery
	}
	for key := range values {
		lower := strings.ToLower(key)
		if strings.HasPrefix(lower, "utm_") || lower == "fbclid" || lower == "gclid" || lower == "ref" || lower == "ref_src" || lower == "mc_cid" || lower == "mc_eid" {
			delete(values, key)
		}
	}
	return values.Encode()
}

var novelWordTokenRe = regexp.MustCompile(`[A-Za-z0-9]+`)
var novelReadingDigitsRe = regexp.MustCompile(`\d+`)

func novelTokens(parts ...string) []string {
	seen := map[string]bool{}
	out := make([]string, 0)
	for _, part := range parts {
		for _, tok := range novelWordTokenRe.FindAllString(strings.ToLower(part), -1) {
			if len(tok) < 4 || novelStopwords[tok] || seen[tok] || novelNumericTokenRe.MatchString(tok) {
				continue
			}
			seen[tok] = true
			out = append(out, tok)
		}
	}
	sort.Strings(out)
	return out
}

func newNovelAskCmd(flags *rootFlags) *cobra.Command {
	var flagInclude []string
	var flagGroupBy string
	var flagFormat string

	cmd := &cobra.Command{
		Use:         "ask <query>",
		Short:       "Assemble every matching highlight and document passage on a topic into note-ready, source-attributed blocks.",
		Example:     `  readwise-pp-cli ask "attention is all you need" --include highlights,docs --group-by source --format md`,
		Annotations: map[string]string{"mcp:read-only": "true", "pp:happy-args": "query=attention"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 && cmd.Flags().NFlag() == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				if flags.asJSON {
					return writeDryRun(cmd.OutOrStdout(), flags, "ask")
				}
				return printDryRunNote(cmd, flags, "would assemble matching highlights and documents into a source-attributed answer")
			}
			if len(args) == 0 || strings.TrimSpace(args[0]) == "" {
				_ = cmd.Usage()
				return usageErr(fmt.Errorf("query is required"))
			}
			query := strings.TrimSpace(args[0])
			include := map[string]bool{}
			if len(flagInclude) == 0 {
				include["highlights"] = true
				include["docs"] = true
			}
			for _, value := range flagInclude {
				for key := range novelCSVSet(value, "") {
					if key == "documents" {
						key = "docs"
					}
					include[key] = true
				}
			}
			if flagGroupBy == "" {
				flagGroupBy = "source"
			}
			if flagFormat == "" {
				flagFormat = "md"
			}
			if flagGroupBy != "source" {
				_ = cmd.Usage()
				return usageErr(fmt.Errorf("unsupported group-by %q", flagGroupBy))
			}

			exists, err := novelLocalStoreExists(cmd)
			if err != nil {
				return err
			}
			askJSON := novelShouldJSON(cmd, flags, flagFormat)
			if cmd.Flags().Changed("format") && flagFormat == "md" && !flags.asJSON {
				askJSON = false
			}
			view := novelAskView{Query: query, Blocks: make([]novelAskBlock, 0), ReturnedCounts: map[string]int{"docs": 0, "highlights": 0}}
			if !exists {
				view.Note = novelMissingLocalDataNote
				if askJSON {
					return printJSONFiltered(cmd.OutOrStdout(), view, flags)
				}
				return novelRenderAskMarkdown(cmd.OutOrStdout(), view)
			}
			db, err := novelOpenStore(cmd)
			if err != nil {
				return err
			}
			defer db.Close()
			docCount, err := novelTableCount(db, "documents")
			if err != nil {
				return fmt.Errorf("count documents: %w", err)
			}
			highlightCount, err := novelTableCount(db, "highlights")
			if err != nil {
				return fmt.Errorf("count highlights: %w", err)
			}
			if (!include["docs"] || docCount == 0) && (!include["highlights"] || highlightCount == 0) {
				view.Note = "No synced documents or highlights found. Run 'readwise-pp-cli sync' first."
				if askJSON {
					return printJSONFiltered(cmd.OutOrStdout(), view, flags)
				}
				return novelRenderAskMarkdown(cmd.OutOrStdout(), view)
			}

			blocks := map[string]*novelAskBlock{}
			order := make([]string, 0)
			if include["highlights"] && highlightCount > 0 {
				raws, err := db.SearchHighlights(query, novelAskSourceLimit+1)
				if err != nil {
					return fmt.Errorf("search highlights: %w", err)
				}
				if len(raws) > novelAskSourceLimit {
					view.Truncated = true
					raws = raws[:novelAskSourceLimit]
				}
				view.ReturnedCounts["highlights"] = len(raws)
				for _, raw := range raws {
					obj := novelRawObject(raw)
					bookID := novelString(obj, "book_id")
					source, bookURL := novelBookSource(db, bookID)
					if source == "" {
						source = novelReadableSource(novelString(obj, "title"), novelString(obj, "author"), "")
					}
					link := novelString(obj, "readwise_url", "url")
					if link == "" {
						link = bookURL
					}
					novelAppendBlock(blocks, &order, source, "highlight", novelSourceItem{
						Text: cliutil.CleanText(novelString(obj, "text")),
						Note: cliutil.CleanText(novelString(obj, "note")),
						URL:  link,
					})
				}
			}
			if include["docs"] && docCount > 0 {
				raws, err := db.SearchTopLevelDocuments(query, novelAskSourceLimit+1)
				if err != nil {
					return fmt.Errorf("search documents: %w", err)
				}
				if len(raws) > novelAskSourceLimit {
					view.Truncated = true
					raws = raws[:novelAskSourceLimit]
				}
				for _, raw := range raws {
					obj := novelRawObject(raw)
					if novelString(obj, "parent_id") != "" {
						continue
					}
					view.ReturnedCounts["docs"]++
					source := novelReadableSource(novelString(obj, "title"), novelString(obj, "author"), novelString(obj, "site_name"))
					summary := novelString(obj, "summary")
					note := cliutil.CleanText(novelString(obj, "notes"))
					text := summary
					if text == "" {
						text = note
						note = ""
					}
					if text == "" {
						text = novelString(obj, "title")
					}
					novelAppendBlock(blocks, &order, source, "document", novelSourceItem{
						Text: text,
						Note: note,
						URL:  novelString(obj, "source_url", "url"),
					})
				}
			}
			for _, key := range order {
				view.Blocks = append(view.Blocks, *blocks[key])
			}
			if askJSON {
				return printJSONFiltered(cmd.OutOrStdout(), view, flags)
			}
			return novelRenderAskMarkdown(cmd.OutOrStdout(), view)
		},
	}
	cmd.Flags().StringSliceVar(&flagInclude, "include", nil, "Comma-separated sources to include: highlights,docs")
	cmd.Flags().StringVar(&flagGroupBy, "group-by", "source", "Group result blocks by source")
	cmd.Flags().StringVar(&flagFormat, "format", "md", "Output format: md or json")
	novelAddDBPathFlag(cmd)
	return cmd
}
